"""Tests for the GET /health endpoint (GitHub issue #3)."""

from collections.abc import Iterator

from fastapi.testclient import TestClient
import pytest

from app.main import app

HEALTH_PATH = "/health"
EXPECTED_BODY = {"status": "healthy"}


@pytest.fixture
def client() -> Iterator[TestClient]:
    """Provide a fresh TestClient per test so no state leaks between tests."""
    with TestClient(app) as test_client:
        yield test_client


@pytest.fixture
def openapi_schema(client: TestClient) -> dict:
    """Return the OpenAPI document generated by the running application."""
    response = client.get("/openapi.json")
    assert response.status_code == 200
    return response.json()


# Acceptance: GET /health returns 200 with {"status": "healthy"} as JSON.


def test_get_health_returns_200(client: TestClient) -> None:
    response = client.get(HEALTH_PATH)

    assert response.status_code == 200


def test_get_health_returns_json_content_type(client: TestClient) -> None:
    response = client.get(HEALTH_PATH)

    assert response.headers["content-type"] == "application/json"


def test_get_health_body_is_exactly_healthy_status(client: TestClient) -> None:
    response = client.get(HEALTH_PATH)

    assert response.json() == EXPECTED_BODY


def test_get_health_body_has_no_extra_fields(client: TestClient) -> None:
    response = client.get(HEALTH_PATH)

    assert set(response.json()) == {"status"}


def test_get_health_is_deterministic_across_repeated_calls(
    client: TestClient,
) -> None:
    first = client.get(HEALTH_PATH)
    second = client.get(HEALTH_PATH)

    assert first.status_code == second.status_code == 200
    assert first.json() == second.json() == EXPECTED_BODY


# Acceptance: no authentication is required (negative/edge input on headers).


def test_get_health_ignores_garbage_authorization_header(client: TestClient) -> None:
    response = client.get(HEALTH_PATH, headers={"Authorization": "Bearer garbage"})

    assert response.status_code == 200
    assert response.json() == EXPECTED_BODY


def test_get_health_without_authorization_header_succeeds(
    client: TestClient,
) -> None:
    response = client.get(HEALTH_PATH, headers={})

    assert response.status_code == 200
    assert response.json() == EXPECTED_BODY


# Boundary: endpoint takes no required input, so extra query input is tolerated.


def test_get_health_ignores_unexpected_query_parameters(client: TestClient) -> None:
    response = client.get(HEALTH_PATH, params={"verbose": "true"})

    assert response.status_code == 200
    assert response.json() == EXPECTED_BODY


# Negative: only GET is supported; other methods are rejected.


@pytest.mark.parametrize("method", ["POST", "PUT", "PATCH", "DELETE"])
def test_non_get_methods_on_health_return_405(client: TestClient, method: str) -> None:
    response = client.request(method, HEALTH_PATH)

    assert response.status_code == 405


def test_405_on_health_advertises_get_in_allow_header(client: TestClient) -> None:
    response = client.post(HEALTH_PATH)

    assert response.status_code == 405
    assert response.headers["allow"] == "GET"


# Negative: the route is exact; similar paths are not health checks.


def test_unknown_similar_path_returns_404(client: TestClient) -> None:
    response = client.get("/healthz")

    assert response.status_code == 404


# Acceptance: OpenAPI documents GET /health with a schema constraining status.


def test_openapi_documents_health_path(openapi_schema: dict) -> None:
    assert HEALTH_PATH in openapi_schema["paths"]


def test_openapi_documents_only_get_method_on_health(openapi_schema: dict) -> None:
    assert set(openapi_schema["paths"][HEALTH_PATH]) == {"get"}


def test_openapi_health_operation_has_summary_and_tag(openapi_schema: dict) -> None:
    operation = openapi_schema["paths"][HEALTH_PATH]["get"]

    assert operation["summary"] == "Application health check"
    assert operation["tags"] == ["health"]


def test_openapi_health_200_response_references_health_response_schema(
    openapi_schema: dict,
) -> None:
    response_200 = openapi_schema["paths"][HEALTH_PATH]["get"]["responses"]["200"]
    schema_ref = response_200["content"]["application/json"]["schema"]["$ref"]

    assert schema_ref == "#/components/schemas/HealthResponse"


def test_openapi_health_response_schema_constrains_status_to_healthy(
    openapi_schema: dict,
) -> None:
    schema = openapi_schema["components"]["schemas"]["HealthResponse"]

    assert schema["type"] == "object"
    assert schema["required"] == ["status"]
    assert schema["properties"]["status"]["type"] == "string"
    assert schema["properties"]["status"]["const"] == "healthy"


# Acceptance: interactive API docs remain reachable alongside the endpoint.


def test_swagger_docs_page_is_reachable(client: TestClient) -> None:
    response = client.get("/docs")

    assert response.status_code == 200
    assert "text/html" in response.headers["content-type"]
    assert "swagger-ui" in response.text
